UPDATE products SET name='Nail Polish By ICE',brand='ICE',description='أضيفي لمسة لون أنيقة إلى يديك مع طلاء الأظافر من آيس. اختيار بسيط لتجديد المانيكير في المنزل، سواء أحببتِ إطلالة يومية هادئة أو لونًا يرافق مناسباتك. حدّدي الدرجة التي تناسبك عند اعتماد التشكيلة.',image_url='/images/catalog/TS0001-54e0b8e9482d.png',details_json='{"nameAr": "طلاء أظافر آيس", "tagline": "تفصيلة صغيرة تغيّر مزاج إطلالتك.", "benefits": ["لون يكمّل إطلالتك", "تجديد سهل للمانيكير", "مناسب لتنسيق ألوانك المفضلة"], "howToUse": "ضعي طبقات رقيقة على أظافر نظيفة وجافة، واتركي كل طبقة تجف قبل التالية.", "notes": "اختاري الدرجة المتاحة؛ صور الألوان لا تغني عن تحديد اسم الدرجة.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0001';
UPDATE products SET name='Nude Contour & Eyeshadow Palette By Dodo Girl',brand='Dodo Girl',description='درجات نود تمنحك مساحة للعب بالظل وتحديد الملامح دون تعقيد روتينك. تساعدك باليت دودو جيرل على الانتقال من لمسة خفيفة للنهار إلى تحديد أوضح للمساء، مع تنسيق الدرجات بحسب إطلالتك ولون بشرتك.',image_url='/images/catalog/TS0002-4f6b4132e536.png',details_json='{"nameAr": "باليت نود للكونتور والظلال من دودو جيرل", "tagline": "باليت واحدة لإطلالة ناعمة ومتناسقة.", "benefits": ["درجات نود قابلة للتنسيق", "تحديد ناعم للملامح", "إطلالات متنوعة من باليت واحدة"], "howToUse": "ابدئي بكمية قليلة بفرشاة مناسبة، ثم ادمجي تدريجيًا. استخدمي كل خانة في المنطقة المحددة على العبوة.", "notes": "تُراجع ألوان الباليت وتفاصيل استخدامها عند اختيار النسخة المتاحة.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0002';
UPDATE products SET name='Jelly Lip Gloss Set By OLIBOLLA',brand='OLIBOLLA',description='لمسة جيلي لامعة تمنح الشفاه مظهرًا حيويًا وتتيح لك تنويع الإطلالة بسهولة. تضم المجموعة خيارات لتنسيق اللمعة مع المكياج اليومي أو فوق لون شفاهك المفضل، لتختاري اللمسة التي تناسب مزاجك.',image_url='/images/catalog/TS0003-0f711204ecc2.png',details_json='{"nameAr": "مجموعة جلوس جيلي للشفاه من أوليبولا", "tagline": "لمعان مرح يضيف الحياة إلى ابتسامتك.", "benefits": ["مظهر لامع للشفاه", "تنويع الإطلالة اليومية", "يمكن تنسيقه مع لون شفاه آخر"], "howToUse": "مرري كمية خفيفة على الشفاه ووزعيها بالتساوي، منفردة أو فوق أحمر الشفاه.", "notes": "تُحدّد ألوان المجموعة وعدد القطع بحسب العبوة المعتمدة.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0003';
UPDATE products SET name='Lip Balm By Rimocoo',brand='Rimocoo',description='حين تحتاج شفاهك إلى استراحة من الجفاف، يمنحك بلسم ريموكو خطوة عناية بسيطة يمكن تجديدها خلال اليوم. اختاريه لإحساس أكثر راحة ولمظهر مرتب قبل الروج أو ضمن روتينك الخفيف من دون مكياج.',image_url='/images/catalog/TS0004-358895a793e1.png',details_json='{"nameAr": "بلسم شفاه ريموكو", "tagline": "نعومة ترافقك في حقيبتك اليومية.", "benefits": ["إحساس أنعم بالشفاه", "عناية سهلة أثناء اليوم", "تهيئة الشفاه للمكياج"], "howToUse": "وزعي طبقة خفيفة على شفاه نظيفة، وجدديها عند الحاجة.", "notes": "تجنبي مشاركته مع الآخرين واحفظي العبوة مغلقة.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0004';
UPDATE products SET name='Gel Color By bobo',brand='bobo',description='لمن تحب تنسيق مانيكيرها مع تفاصيل إطلالتها، يتيح جل بوبو إضافة لون مميز للأظافر. تتوقف طريقة التطبيق والتجفيف على النسخة الفعلية، لذلك نحرص على تحديد نظام المنتج والدرجة قبل اعتماده للبيع.',image_url='/images/catalog/TS0005-afa322d2d52c.jpg',details_json='{"nameAr": "جل تلوين الأظافر من بوبو", "tagline": "إطلالة أظافر لامعة على طريقتك.", "benefits": ["تنسيق لون الأظافر", "لمسة مرتبة لليدين", "درجات تناسب إطلالات مختلفة"], "howToUse": "اتبعي نظام التحضير والتجفيف المدون على العبوة، بما فيه جهاز التجفيف إذا كانت النسخة تتطلبه.", "notes": "لا تعاملي طلاء الجل كطلاء عادي قبل التحقق من تعليمات العبوة.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0005';
UPDATE products SET name='Ultimate Dream Eyeshadow Palette By Diamond Beauty',brand='Diamond Beauty',description='اصنعي إطلالة عين تعبّر عنك مع باليت ألتيميت دريم. يمكنك توزيع الدرجات الفاتحة لإضاءة الجفن وبناء العمق بالدرجات الأغمق، لتبقى شدة اللون بيدك من بداية التطبيق حتى اللمسة الأخيرة.',image_url='/images/catalog/TS0006-daf240317120.png',details_json='{"nameAr": "باليت ظلال ألتيميت دريم من دايموند بيوتي", "tagline": "من نظرة ناعمة إلى حضور مسائي.", "benefits": ["تنويع إطلالات العين", "مزج درجات متكاملة", "بناء كثافة اللون تدريجيًا"], "howToUse": "ضعي كمية قليلة بفرشاة ظلال، وادمجي الحواف قبل إضافة طبقة أخرى.", "notes": "تجنبي إدخال البودرة إلى العين، واختاري النسخة ودرجاتها المحددة.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0006';
UPDATE products SET name='9 Color Eyeshadow Palette By MERRYCOLOR',brand='MERRYCOLOR',description='باليت صغيرة تساعدك على تجربة تنسيقات مختلفة للعين دون الحاجة إلى قطع كثيرة. اختاري درجة أساسية ثم أضيفي تحديدًا أو لمعة بحسب الألوان الفعلية في الباليت، لتحصلي على إطلالة تناسب يومك.',image_url='/images/catalog/TS0007-513d8ec6f9c3.png',details_json='{"nameAr": "باليت 9 ألوان للعيون من ميري كولور", "tagline": "تسعة اختيارات لمساحة أكبر من الإبداع.", "benefits": ["تسع درجات في عبوة واحدة", "تسهيل تنسيق الظلال", "تحكم في قوة الإطلالة"], "howToUse": "طبقي الظلال على الجفن بفرشاة نظيفة، وابني اللون بخفة وادمجي جيدًا.", "notes": "تُحدّد لوحة الألوان المتاحة قبل اعتماد المنتج.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0007';
UPDATE products SET name='Color Shifter Highlighter Palette By Romantic Bright',brand='Romantic Bright',description='أبرزي الأماكن التي تحبينها بلمسة إضاءة قابلة للبناء. باليت كولور شيفتر تضيف بعدًا مضيئًا إلى المكياج، ويمكنك الاكتفاء بوهج خفيف أو تعزيز اللمعة لمناسباتك بحسب طريقة التطبيق والدرجة المختارة.',image_url='/images/catalog/TS0008-f9a58c303c2e.png',details_json='{"nameAr": "باليت هايلايتر كولور شيفتر من رومانتيك برايت", "tagline": "نقاط ضوء تمنح ملامحك حضورًا.", "benefits": ["إبراز أعلى الخد", "لمعة قابلة للبناء", "تنسيق الإضاءة مع المكياج"], "howToUse": "مرري كمية خفيفة بفرشاة هايلايتر على مناطق الإضاءة، ثم زيديها تدريجيًا.", "notes": "ابدئي بكمية قليلة لتختاري شدة اللمعة التي تفضلينها.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0008';
UPDATE products SET name='Hair Care Oil Macadamia & Vitamin E By FREELOOK',brand='FREELOOK',description='امنحي أطراف شعرك عناية تكمل التصفيف مع زيت فري لوك بالمكاديميا. يساعد على تلطيف الإحساس بالخشونة وتحسين مظهر الهيشان، ويضيف إلى روتينك لمسة نهائية تناسب الشعر الذي يبدو جافًا عند الأطراف.',image_url='/images/catalog/TS0009-82df1eda5621.png',details_json='{"nameAr": "زيت عناية بالمكاديميا من فري لوك", "tagline": "أطراف أنعم ولمسة نهائية أجمل.", "benefits": ["تنعيم مظهر الأطراف", "تقليل مظهر الهيشان", "تجميل اللمسة النهائية للتصفيف"], "howToUse": "وزعي كمية صغيرة بين راحتيك ثم مرريها على الأطوال والأطراف، وزيدي حسب الحاجة.", "notes": "ابدئي بالقليل لتجنب إثقال الشعر، خاصة الشعر الناعم.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0009';
UPDATE products SET name='Hair Care Oil With Keratin & Vitamin E By FREELOOK',brand='FREELOOK',description='إذا كانت الأطراف المتطايرة تفسد مظهر التسريحة، أضيفي زيت فري لوك بالكيراتين إلى خطوة العناية النهائية. يمنح الأطوال ملمسًا أكثر نعومة ويساعد على تحسين مظهر الشعر بعد التصفيف دون الحاجة إلى استخدام كمية كبيرة.',image_url='/images/catalog/TS0010-f45a7a45f7a3.png',details_json='{"nameAr": "زيت عناية بالكيراتين من فري لوك", "tagline": "لشعر يبدو أكثر ترتيبًا وانسيابية.", "benefits": ["مظهر أطراف مرتب", "إحساس أنعم بالأطوال", "لمسة عناية بعد التصفيف"], "howToUse": "مرري كمية قليلة على الأطوال والأطراف مع توزيعها جيدًا بعيدًا عن الجذور عند عدم الحاجة.", "notes": "المنتج خطوة تجميلية للعناية؛ لا يعيد وصل الشعر المتقصف.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0010';
UPDATE products SET name='Floral Shimmer Fragrance Lotion By DERMOKIL',brand='DERMOKIL',description='امنحي بشرة جسمك لحظة تدليل تجمع الترطيب والإطلالة المضيئة. لوشن فلورال شيمر يضيف إلى روتينك إحساسًا ناعمًا ولمسة عطرية، ويليق بالأيام التي ترغبين فيها بإظهار الساقين أو الذراعين بوهج خفيف.',image_url='/images/catalog/TS0011-aa3f5f66e72e.png',details_json='{"nameAr": "لوشن الجسم فلورال شيمر من ديرموكيل", "tagline": "عناية للجسم مع لمعة لطيفة.", "benefits": ["نعومة لبشرة الجسم", "لمسة مضيئة", "تجربة عناية عطرية"], "howToUse": "وزعي كمية مناسبة على الجسم ودلكي حتى يتوزع اللوشن، واتركيه يمتص قبل ارتداء الملابس.", "notes": "للاستخدام على الجسم؛ تجنبي الوجه والمناطق المتهيجة.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0011';
UPDATE products SET name='Argan Steam Hair Care Mask By DERMOKIL',brand='DERMOKIL',description='امنحي شعرك وقتًا إضافيًا من الاهتمام مع ماسك الأرغان البخاري. صُمم كخطوة عناية مكثفة للأطوال التي تبدو جافة أو خشنة، ليساعدك على الحصول على ملمس أنعم وتسريح أكثر سهولة ضمن روتين الغسل.',image_url='/images/catalog/TS0012-f296cc27747b.png',details_json='{"nameAr": "ماسك الشعر البخاري بالأرغان من ديرموكيل", "tagline": "استراحة عناية لأطوال تحتاج نعومة.", "benefits": ["تلطيف ملمس الشعر", "عناية بالأطوال الجافة", "تسهيل التسريح"], "howToUse": "طبقيه بالطريقة والمدة المحددتين على العبوة، ووزعيه على الأطوال ثم اشطفي إذا كانت التعليمات تتطلب ذلك.", "notes": "راجعي طريقة تفعيل الغطاء أو القناع البخاري في العبوة الفعلية.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0012';
UPDATE products SET name='Vitamin C Anti-Spot & Sun Protection Hand Mask By DERMOKIL',brand='DERMOKIL',description='بعد الغسل المتكرر والأعمال اليومية، امنحي يديك لحظة عناية خاصة. يساعد هذا الماسك على تلطيف ملمس الجلد وتحسين مظهر الجفاف، لتخرجي من روتين العناية بيدين تبدوان أكثر نعومة واهتمامًا.',image_url='/images/catalog/TS0013-985905f03e2d.png',details_json='{"nameAr": "ماسك اليدين بفيتامين سي من ديرموكيل", "tagline": "لليدين اللتين تستحقان عناية إضافية.", "benefits": ["عناية بملمس اليدين", "تلطيف مظهر الجفاف", "خطوة تدليل منزلية"], "howToUse": "استخدمي الماسك على يدين نظيفتين للمدة المدونة على العبوة، ثم اتبعي تعليمات الإزالة.", "notes": "لا يعوض واقي الشمس؛ تُراجع معلومات الحماية على العبوة قبل اعتمادها.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0013';
UPDATE products SET name='Clay and Hemp Oil Exfoliating Hand Mask By DERMOKIL',brand='DERMOKIL',description='لليدين اللتين تبدوان خشنتين أو باهتتين، يضيف ماسك الطين خطوة عناية مخصصة لملمس الجلد. استخدميه ضمن روتين متباعد واتبعيه بمرطب يدين، لتحافظي على إحساس أكثر راحة ونعومة بعد العناية.',image_url='/images/catalog/TS0014-a33bdf5bc446.png',details_json='{"nameAr": "ماسك تقشير اليدين بالطين من ديرموكيل", "tagline": "نعومة تبدأ من العناية بملمس اليدين.", "benefits": ["العناية بخشونة الملمس", "روتين مخصص لليدين", "تهيئة اليدين للترطيب"], "howToUse": "اتبعي طريقة التطبيق والمدة والتكرار الموضحة على العبوة دون زيادة.", "notes": "لا يطبق على الجلد المتشقق أو الجروح، وتجنبي الفرك القوي.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0014';
UPDATE products SET name='Repairing and Nourishing Hand Mask By DERMOKIL',brand='DERMOKIL',description='أعيدي الاهتمام إلى يديك مع ماسك يمنح الجلد إحساسًا بالترطيب والنعومة. يلائم روتين العناية المنزلية لليدين بعد التعرض المتكرر للماء، ويضيف خطوة تدليل مريحة قبل استكمال مرطبك المعتاد.',image_url='/images/catalog/TS0015-654447698ccb.png',details_json='{"nameAr": "ماسك ترطيب وتجديد اليدين من ديرموكيل", "tagline": "لحظة راحة بعد يوم طويل.", "benefits": ["إحساس بالترطيب", "تلطيف ملمس اليدين", "عناية منزلية بسيطة"], "howToUse": "طبقيه على يدين نظيفتين حسب مدة العبوة، ووزعي بقايا العناية إذا كانت التعليمات تسمح.", "notes": "توقفي عن استخدامه عند ظهور تهيج.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0015';
UPDATE products SET name='Vitamin C Peel-Off Foot Mask with Exfoliating Effect By DERMOKIL',brand='DERMOKIL',description='امنحي قدميك روتينًا يتجاوز الترطيب السريع. يساعد هذا الماسك المقشر على العناية بمظهر الجلد الخشن، وتختلف مراحل التقشير بحسب نوع القناع والعبوة؛ لذلك يبقى الالتزام بالتعليمات جزءًا أساسيًا من التجربة.',image_url='/images/catalog/TS0016-e9e0f8aae53c.png',details_json='{"nameAr": "ماسك تقشير القدمين بفيتامين سي من ديرموكيل", "tagline": "عناية مخصصة لنعومة القدمين.", "benefits": ["العناية بملمس القدمين", "تقليل مظهر الخشونة", "خطوة عناية منزلية متخصصة"], "howToUse": "اتبعي مدة ارتداء الماسك وتعليمات الغسل المدونة على العبوة، ثم رطبي القدمين حسب الإرشادات.", "notes": "لا تنزعي الجلد بالقوة ولا تستخدميه على التشققات المفتوحة.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0016';
