UPDATE products SET name='10% Urea Heel Crack Care & Moisturizing Foot Mask By DERMOKIL',brand='DERMOKIL',description='امنحي منطقة الكعب عناية موجهة بدل الاكتفاء بترطيب سريع للقدم كلها. يساعد هذا الماسك على تلطيف مظهر الجلد الجاف والخشن، ويكمل روتين الترطيب المنتظم للحصول على ملمس أكثر راحة.',image_url='/images/catalog/TS0019-95a043026017.png',details_json='{"nameAr": "ماسك العناية بالكعبين باليوريا من ديرموكيل", "tagline": "اهتمام مركز بخشونة الكعبين.", "benefits": ["عناية بخشونة الكعب", "تلطيف مظهر الجفاف", "إحساس أنعم بالقدمين"], "howToUse": "اتبعي طريقة الماسك ومدة بقائه على العبوة، واستخدميه على جلد سليم.", "notes": "التشققات النازفة أو المؤلمة تحتاج تقييمًا مناسبًا قبل مستحضرات التقشير.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0019';
