UPDATE products SET name='Rice Yeast Whitening Fluid Cream 30 SPF By DERMOKIL',brand='DERMOKIL',description='لمن تفضل مرطبًا سهل التوزيع، يضيف كريم رايس ييست خطوة عناية تساعد البشرة على الظهور بملمس أكثر نعومة وانتعاشًا. اختاريه ضمن روتين يراعي احتياج بشرتك للترطيب مع استكمال الحماية من الشمس.',image_url='/images/catalog/TS0021-3043f5e0bb7d.png',details_json='{"nameAr": "كريم رايس ييست المرطب من ديرموكيل", "tagline": "ترطيب بإحساس خفيف لروتين النهار.", "benefits": ["تلطيف ملمس البشرة", "إحساس يومي بالترطيب", "سهولة دمجه بالروتين"], "howToUse": "طبقي كمية مناسبة على بشرة نظيفة، واتّبعي تعليمات العبوة بشأن الاستخدام النهاري.", "notes": "لا نعتمد درجة حماية شمسية للمنتج قبل التحقق من العبوة الفعلية.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0021';
