UPDATE products SET name='سيروم الهيالورونيك أسيد The Ordinary Hyaluronic Acid 2%+B5',brand='The Ordinary',description='إذا بدت بشرتك مشدودة أو باهتة، يضيف هذا السيروم خطوة ترطيب خفيفة قبل الكريم. يساعد على تحسين الإحساس بالنعومة ومظهر الخطوط المرتبطة بالجفاف، ليصبح روتينك اليومي أكثر راحة وتوازنًا.',image_url='/images/catalog/TS0026-65cf674a2df1.jpg',details_json='{"nameAr": "سيروم هيالورونيك أسيد مع B5 من ذا أورديناري", "tagline": "ترطيب يمنح الملمس مظهرًا أكثر امتلاءً.", "benefits": ["إحساس أكثر ترطيبًا", "تنعيم مظهر الملمس", "تهيئة البشرة للمرطب"], "howToUse": "ضعي كمية قليلة بعد تنظيف البشرة، ثم أتبعيه بمرطب مناسب.", "notes": "تجنبي محيط العين المباشر إذا كانت العبوة لا تخصصه لذلك.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0026';
