UPDATE products SET name='AHA 30%+BHA 2% Peeling Solution By The Ordinary',brand='The Ordinary',description='هذا المقشر خيار مركز لمن لديها خبرة باستخدام الأحماض وتريد العناية ببهتان البشرة وتفاوت ملمسها. يساعد على تحسين مظهر السطح والمسام، ويحتاج التزامًا دقيقًا بتعليمات الشركة بدل استخدامه كسيروم يومي أو ماسك ليلي.',image_url='/images/catalog/TS0028-cdfedf418b07.jpg',details_json='{"nameAr": "محلول التقشير الأحمر من ذا أورديناري", "tagline": "خطوة تقشير متقدمة لملمس أكثر صفاءً.", "benefits": ["تحسين مظهر الملمس", "العناية ببهتان البشرة", "تقشير مخصص للمستخدمات المتمرسات"], "howToUse": "على بشرة نظيفة وجافة تمامًا مساءً، بعيدًا عن العينين. يشطف قبل تجاوز 10 دقائق، وبحد أقصى مرتين أسبوعيًا وفق تعليمات الشركة.", "notes": "لا يناسب البشرة الحساسة أو المتضررة. اختبريه موضعيًا، واستخدمي واقي شمس وتوقفي عند التهيج.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0028';
