UPDATE products SET name='مثبت مكياج Dr.Rashel',brand='Dr Rashel',description='أكملي المكياج برذاذ يساعد على توحيد مظهر طبقاته ومنح الإطلالة لمسة نهائية مرتبة. يناسب من تحب إضافة خطوة تثبيت بعد البودرة أو الفاونديشن، مع اختيار القوام الذي ينسجم مع نوع بشرتها.',image_url='/images/catalog/TS0033-81da2d7c9704.jpg',details_json='{"nameAr": "بخاخ تثبيت المكياج من دكتور راشيل", "tagline": "اللمسة الأخيرة بعد إتمام إطلالتك.", "benefits": ["إنهاء خطوات المكياج", "تلطيف مظهر الطبقات", "توزيع برذاذ خفيف"], "howToUse": "رشي بالمسافة المحددة على العبوة بعد المكياج مع إغلاق العينين والفم، واتركيه يجف.", "notes": "لا يرش داخل العين ولا يستخدم على جلد متهيج.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0033';
UPDATE products SET name='كريم فيتامين أي والريتينول لرفع العين ومكافحة الشيخوخة من Dr Rashel',brand='Dr Rashel',description='امنحي محيط العين خطوة عناية تركز على الترطيب ومظهر النعومة. هذا الكريم مخصص للمنطقة التي قد تبدو عليها علامات الجفاف والتعب، ويحتاج استخدامًا خفيفًا وفق تعليمات العبوة لأن منطقة العين أكثر حساسية.',image_url='/images/catalog/TS0034-29fee2409fd6.jpg',details_json='{"nameAr": "كريم العين بفيتامين E والريتينول من دكتور راشيل", "tagline": "اهتمام بمظهر الخطوط الدقيقة حول العين.", "benefits": ["ترطيب لمحيط العين", "تحسين مظهر الخطوط المرتبطة بالجفاف", "قوام كريم لروتين العناية"], "howToUse": "ربتي بكمية صغيرة في المنطقة المسموح بها على العبوة، واتبعي تواتر الاستخدام المحدد عليها.", "notes": "لا يدخل إلى العين، ويُدخل إلى الروتين تدريجيًا إذا احتوى على الريتينول.", "imageType": "photo", "collection": "beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0034';
