UPDATE products SET name='medicube - Collagen Jelly Cream (110ml)',brand='Medicube',description='امنحي البشرة إحساسًا نديًا مع كريم الكولاجين الجيلي من ميديكيوب. يوزع بسهولة كخطوة ترطيب بعد السيرومات، ويساعد على تحسين مظهر الجفاف ليصبح الوجه أكثر نعومة وحيوية في روتينك المعتاد.',image_url='/images/catalog/TS0083-db815bac5be6.jpg',details_json='{"nameAr": "كريم كولاجين جيلي من ميديكيوب", "tagline": "ترطيب بقوام جيلي ينعش روتينك.", "benefits": ["إحساس ندي بالترطيب", "قوام جيلي", "تلطيف مظهر الجفاف"], "howToUse": "وزعي كمية مناسبة على الوجه بعد السيروم وربتي حتى يتوزع.", "notes": "ابدئي بكمية خفيفة إذا كانت بشرتك تميل إلى اللمعان.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0083';
