UPDATE products SET name='Beauty of Joseon - Red Bean Refreshing Pore Mask',brand='Beauty of Joseon',description='أضيفي جلسة ماسك تهتم بمظهر دهون السطح والملمس غير المتجانس. ماسك ريد بين يكمّل الغسول والترطيب بخطوة متباعدة، ويمنحك إحساسًا بالنظافة عندما تريدين تدليل بشرتك دون روتين طويل.',image_url='/images/catalog/TS0100-4d24d71ad091.jpg',details_json='{"nameAr": "ماسك ريد بين للمسام من بيوتي أوف جوسون", "tagline": "استراحة عناية لملمس يبدو أكثر نقاءً.", "benefits": ["العناية بدهون السطح", "تحسين مظهر الملمس", "جلسة ماسك منزلية"], "howToUse": "وزعي على بشرة نظيفة بالطريقة والمدة المحددتين على العبوة ثم اشطفي بلطف.", "notes": "لا تتركيه مدة أطول على أمل نتيجة أسرع، وتجنبي الجلد المتهيج.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0100';
UPDATE products SET name='Beauty of Joseon - Relief Sun Mini',brand='Beauty of Joseon',description='احملي خطوة الحماية المفضلة لديك بحجم أصغر، مناسب لتجربة قوام ريليف صن أو وضعه في حقيبة اليوم. تبقى طريقة الاستخدام والكمية الكافية مهمة كما في العبوة الكبيرة، حتى عند استخدام حجم السفر.',image_url='/images/catalog/TS0101-cdeffd530221.jpg',details_json='{"nameAr": "واقي ريليف صن بالحجم المصغّر من بيوتي أوف جوسون", "tagline": "رفيق صغير لتجربة روتينك وحقيبتك.", "benefits": ["عبوة صغيرة للحقيبة", "تجربة قوام المنتج", "سهولة اصطحاب الواقي"], "howToUse": "وزعي كمية كافية وفق العبوة وجددي عند التعرض للشمس.", "notes": "الحجم المصغر خيار مختلف عن العبوة الكبيرة ولا يعني استخدام كمية أقل لكل تطبيق.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0101';
