UPDATE products SET name='JUMISO - Niacinamide 5+ Overnight Cream 50 ml',brand='JUMISO',description='اختتمي اليوم بكريم يضيف إلى الترطيب اهتمامًا بمظهر تفاوت اللون والملمس. يساعدك كريم جوميسو الليلي على تنسيق خطوة ختامية للروتين، ليبقى إحساس البشرة أكثر نعومة وراحة بعد العناية.',image_url='/images/catalog/TS0174-f8d3582f64e9.jpg',details_json='{"nameAr": "كريم نياسيناميد 5+ الليلي من جوميسو", "tagline": "ترطيب للمساء مع عناية بمظهر النضارة.", "benefits": ["ترطيب للمساء", "العناية بمظهر النضارة", "خطوة كريم ختامية"], "howToUse": "وزعي كمية مناسبة بعد السيروم في روتين المساء بحسب إرشادات العبوة.", "notes": "لا تفرطي في طبقات العناية إذا شعرتِ بالثقل أو اللمعان الزائد.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0174';
