UPDATE products SET name='medicube - PDRN Pink Collagen Exosome Shot Serum 7500 30 ml',brand='Medicube',description='امنحي روتينك الليلي اهتمامًا بمظهر البشرة غير المتجانس مع نسخة شوت 7500 الوردية. تجمع فكرة العناية المكثفة ومظهر النضارة، وتحتاج استخدامًا حسب تعليمات العبوة بدل معاملتها كسيروم ترطيب عادي يصلح بكل تواتر.',image_url='/images/catalog/TS0176-f3c2ebf06d5e.jpg',details_json='{"nameAr": "سيروم PDRN بينك إكسوسوم 7500 من ميديكيوب", "tagline": "عناية متخصصة بمظهر المرونة والملمس.", "benefits": ["العناية بمظهر الملمس", "تحسين مظهر المرونة", "خطوة عناية مكثفة"], "howToUse": "اتبعي الكمية وتواتر الاستخدام الخاصين بهذه النسخة ثم استكملي مرطبًا مناسبًا.", "notes": "قد يصاحبه وخز؛ لا يجمع عشوائيًا مع تقشير قوي أو على جلد متهيج.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0176';
UPDATE products SET name='APRILSKIN - TXA Niacinamide 99 Milky Toner 150 ml',brand='APRILSKIN',description='أضيفي بعد التنظيف خطوة تونر حليبية تركز على مظهر البهتان والترطيب. يهيئ 99 ميلكي البشرة للسيروم والكريم، ويليق بمن تحب أن تبدأ عنايتها بقوام مريح بدل الاكتفاء بمنتج واحد كثيف.',image_url='/images/catalog/TS0177-1521fede5d9a.jpg',details_json='{"nameAr": "تونر 99 ميلكي من أبريل سكين", "tagline": "طبقة عناية حليبية لمظهر أكثر إشراقًا.", "benefits": ["قوام حليبي", "إحساس بالترطيب", "العناية بمظهر البهتان"], "howToUse": "وزعي براحة اليد أو بالطريقة المحددة على العبوة ثم أكملي خطوات العناية.", "notes": "يختلف التونر عن سيروم Toning Shot 99 من المجموعة نفسها.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0177';
UPDATE products SET name='Dr. Althea - Aqua Glowing Sunscreen',brand='Dr. Althea',description='أضيفي إلى الصباح واقي أكوا غلوينغ من دكتور ألثيا عندما تفضلين قوامًا ينسجم مع العناية المرطبة. يساعدك على إدخال الحماية ضمن روتين يومي منظم، مع الكمية الكافية وتجديدها خلال التعرض للشمس.',image_url='/images/catalog/TS0178-914b749f375d.jpg',details_json='{"nameAr": "واقي أكوا غلوينغ من دكتور ألثيا", "tagline": "حماية نهارية تكمّل الإطلالة الندية.", "benefits": ["حماية نهارية", "إحساس بالعناية المرطبة", "تنسيق سهل مع المكياج"], "howToUse": "وزعي وفق تعليمات العبوة وجددي أثناء التعرض للشمس وبعد التعرق أو السباحة.", "notes": "هذه نسخة Aqua Glowing، وتختلف عن Purifying Green Tea في التشكيلة.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0178';
UPDATE products SET name='Centellian24 - Madeca Cream Time Reverse 50 ml',brand='Centellian24',description='امنحي البشرة الجافة أو المرهقة كريمًا يركز على إحساس العناية ومظهر المرونة. ماديكا تايم ريفيرس يضيف طبقة ترطيب مريحة بعد السيروم، ليكمل روتينًا يهتم بتلطيف الجفاف وتحسين مظهر الملمس.',image_url='/images/catalog/TS0179-eaa69d8f2bb8.jpg',details_json='{"nameAr": "كريم ماديكا تايم ريفيرس من سنتيليان 24", "tagline": "عناية بملمس يبدو أكثر نعومة ومرونة.", "benefits": ["إحساس بالترطيب", "العناية بمظهر المرونة", "خطوة كريم مريحة"], "howToUse": "وزعي كمية مناسبة على الوجه بعد خطوات العناية الأخف وفق العبوة.", "notes": "راجعي اسم النسخة كاملًا لأن مجموعة ماديكا تضم إصدارات مختلفة.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0179';
UPDATE products SET name='KSECRET - Collagen Boosting Secret Sleeping Mask 60 ml',brand='KSECRET',description='أضيفي إلى الليل ماسكًا يكمّل الترطيب ويمنح البشرة إحساسًا بالعناية. كولاجين بوستنغ من كيه سيكرت ينسجم مع روتين بسيط قبل النوم، عندما تريدين مظهرًا أنعم وشعورًا أقل جفافًا بعد العناية.',image_url='/images/catalog/TS0180-0b6f4397067d.png',details_json='{"nameAr": "ماسك النوم كولاجين بوستنغ من كيه سيكرت", "tagline": "اللمسة الأخيرة لعناية المساء.", "benefits": ["تكملة لترطيب المساء", "ملمس أنعم", "خطوة ختامية للروتين"], "howToUse": "طبقي بالطريقة والكمية المحددتين على العبوة كخطوة أخيرة في المساء.", "notes": "اتبعي تعليمات الشركة حول الشطف أو الإزالة صباحًا.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0180';
