UPDATE products SET name='Arencia - Retinal Booster Shot 30 ml',brand='Arencia',description='لمن تريد إدخال الريتينال إلى روتين واضح، يقدم بوستر أرينسيا عناية مركزة بمظهر النعومة والخطوط الدقيقة. يرافقه التدرج والاهتمام بالترطيب، مع اختيار وقت مناسب لإدخال مستحضر جديد ومراقبة الاستجابة.',image_url='/images/catalog/TS0183-e5b1240ef265.jpg',details_json='{"nameAr": "ريتينال بوستر شوت من أرينسيا", "tagline": "خطوة ليلية بمظهر الملمس والخطوط.", "benefits": ["العناية بمظهر الخطوط", "تحسين مظهر الملمس", "خطوة مركزة للمساء"], "howToUse": "استخدمي كمية صغيرة حسب تواتر العبوة، ثم أكملي مرطبًا مناسبًا.", "notes": "لا يجمع مع ريتينويد آخر في الروتين نفسه، وتستخدم الحماية من الشمس نهارًا.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0183';
UPDATE products SET name='numbuzin - No.9 NAD Bio Lifting-sil',brand='Numbuzin',description='امنحي وجهك وقتًا خاصًا مع ماسك رقم 9 من نمبوزين. يركز على إحساس الترطيب ومظهر النعومة والمرونة، ليكون خطوة تدليل عند الحاجة إلى عناية إضافية أو قبل إطلالة ترغبين أن تبدو أكثر نضارة.',image_url='/images/catalog/TS0184-80ce733cdb64.png',details_json='{"nameAr": "ماسك رقم 9 NAD من نمبوزين", "tagline": "جلسة عناية لملمس أكثر حيوية.", "benefits": ["إحساس بالترطيب", "تحسين مظهر النعومة", "جلسة عناية مريحة"], "howToUse": "ثبتي القناع على بشرة نظيفة للمدة المحددة على العبوة ثم أزيليه بلطف.", "notes": "اختاري نسخة No.9 المحددة واتّبعي طريقة تثبيت أجزائها.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0184';
UPDATE products SET name='Anua - Retinol 0.1 Caffeine Revitalizing Eye Cream 30 ml',brand='ANUA',description='أضيفي لمحيط العين عناية مركزة تجمع الاهتمام بمظهر التعب والنعومة. كريم أنوا لهذه المنطقة يحتاج كمية صغيرة وتدرجًا في الاستخدام، ليكمل روتينًا منظمًا بدل زيادة المستحضرات حول العين بصورة عشوائية.',image_url='/images/catalog/TS0185-517ef68a4986.png',details_json='{"nameAr": "كريم العين ريتينول 0.1 كافيين من أنوا", "tagline": "اهتمام ليلي بمظهر التعب والخطوط.", "benefits": ["العناية بمظهر الخطوط الدقيقة", "ترطيب محيط العين", "اهتمام بمظهر التعب"], "howToUse": "طبقي وفق تعليمات العبوة حول عظمة العين دون إدخاله إليها، وابدئي بتدرج مناسب.", "notes": "يحتوي على ريتينول؛ لا يجمع مع مستحضر ريتينويد آخر في المنطقة نفسها.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0185';
UPDATE products SET name='d''Alba - White Truffle First Spray Serum (أحجام مختلفة في الوصف)',brand='d''Alba',description='امنحي بشرتك رذاذ عناية يضيف إحساسًا بالترطيب ولمسة ندية إلى الإطلالة. يليق بخطوة قبل المكياج أو خلال اليوم بحسب تعليمات العبوة، مع رج المستحضر عندما تتطلب تركيبته ذلك لتتوزع طبقاته جيدًا.',image_url='/images/catalog/TS0186-b8a8d7a7f6c3.jpg',details_json='{"nameAr": "بخاخ وايت ترافل فيرست سيروم من دالبا", "tagline": "لمسة نضارة يمكن تجديدها بسهولة.", "benefits": ["توزيع بالرذاذ", "إحساس بالترطيب", "لمسة إطلالة ندية"], "howToUse": "رجي العبوة إن نصت التعليمات ثم رشي بالمسافة المحددة مع إغلاق العينين.", "notes": "تتوفر أحجام متعددة؛ يجب اختيار الحجم المتاح قبل اعتماد المنتج للبيع.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0186';
UPDATE products SET name='EQQUALBERRY - Hyaltoin Flooding Serum 30 ml',brand='EQQUALBERRY',description='امنحي البشرة التي تشعر بالشد خطوة سيروم تركز على إحساس الترطيب ونعومة الملمس. يندمج هيالتوين فلودنغ قبل الكريم ليكمل روتينًا يهتم بمظهر أكثر امتلاءً ونضارة دون الحاجة إلى طبقات كثيرة.',image_url='/images/catalog/TS0187-af9ea50a2313.webp',details_json='{"nameAr": "سيروم هيالتوين فلودنغ من إكوالبيري", "tagline": "ترطيب ينعش مظهر البشرة الجافة.", "benefits": ["إحساس بالترطيب", "تلطيف مظهر الجفاف", "تهيئة البشرة للكريم"], "howToUse": "وزعي كمية مناسبة بعد تنظيف الوجه ثم أتبعيها بمرطب يحافظ على راحة البشرة.", "notes": "عدلي الكمية بحسب حاجة المناطق المختلفة من الوجه.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0187';
UPDATE products SET name='Dr. Althea - Aqua Marine Deep Serum 30 ml',brand='Dr. Althea',description='إذا كنتِ تفضلين سيرومًا يضيف العناية دون قوام كريم كثيف، تعرفي إلى أكوا مارين ديب. يركز على إحساس الترطيب وتلطيف مظهر الجفاف، ليكون خطوة سهلة قبل المرطب ضمن روتين صباحي أو مسائي يناسب بشرتك.',image_url='/images/catalog/TS0188-e00dc89f8f5b.jpg',details_json='{"nameAr": "سيروم أكوا مارين ديب من دكتور ألثيا", "tagline": "ترطيب خفيف بلمسة منعشة.", "benefits": ["قوام سيروم خفيف", "إحساس منعش بالترطيب", "تلطيف مظهر الجفاف"], "howToUse": "وزعي كمية صغيرة بعد التنظيف وقبل المرطب وفق إرشادات العبوة.", "notes": "أكملي الحماية من الشمس عند استخدامه في روتين النهار.", "imageType": "photo", "collection": "k-beauty", "featuredOrder": 100}',active=1,updated_at=datetime('now') WHERE id='TS0188';
